package com.joysistvi.CyberAccess.service;
import com.joysistvi.CyberAccess.model.Food; import com.joysistvi.CyberAccess.repo.*; import java.sql.SQLException; import java.util.List;
public class FoodServiceImpl { private final FoodRepo repo; public FoodServiceImpl(){this(new FoodRepoImpl());} public FoodServiceImpl(FoodRepo r){repo=r;}
 public List<Food> getAll()throws SQLException{return repo.findAll();} public List<Food> getByCategory(int id)throws SQLException{return repo.findByCategory(Validation.id(id));} public Food getById(int id)throws SQLException{return repo.findById(Validation.id(id)).orElse(null);} public void add(Food x)throws SQLException{validate(x);repo.save(x);} public boolean update(Food x)throws SQLException{validate(x);Validation.id(x.getId());return repo.update(x);} public boolean delete(int id)throws SQLException{return repo.delete(Validation.id(id));} private void validate(Food x){if(x==null)throw new IllegalArgumentException("Food is required.");x.setFood(Validation.text(x.getFood(),"Food name",50));Validation.id(x.getCategoryId()); if(x.getPrice()==null || x.getPrice().signum()<0) throw new IllegalArgumentException("Food price must be zero or greater.");}}
